import { DrillDownBreadcrumbConfig } from 'pages/pillars/ValueCreation/hooks/useDrillDownBreadcrumb';
import { hasDrillDownSpecificFilterValue } from 'pages/pillars/ValueCreation/utils/drillDownBreadcrumbUtils';

import {
  PERFORMANCE_TOOL_PAGE_NAME,
  WATERFALL_RESET_EVENT,
} from '../constants';
import {
  buildPerformanceToolDrillDownClearPatch,
  PERFORMANCE_TOOL_DRILL_DOWN_DIMENSION_KEYS,
  type PerformanceToolDrillDownDimensionKey,
} from '../performanceToolClearDrillDown';

export const PERFORMANCE_TOOL_BREADCRUMB_CONFIG: DrillDownBreadcrumbConfig<PerformanceToolDrillDownDimensionKey> =
  {
    pageName: PERFORMANCE_TOOL_PAGE_NAME,
    goldenPathOrder: PERFORMANCE_TOOL_DRILL_DOWN_DIMENSION_KEYS,
    navOrderParam: 'nav_pt_order',
    resetEvent: WATERFALL_RESET_EVENT,
    hasSpecificValue: hasDrillDownSpecificFilterValue,
    buildClearPatch: (defaults, keysToClean, keysToKeep, currentApplied) =>
      buildPerformanceToolDrillDownClearPatch(
        defaults,
        keysToClean,
        keysToKeep,
        currentApplied,
      ),
  };
